#include <stdlib.h>
#include <string.h>
#include <omp.h>

/* Portable GEMM using GCC vector extensions; register tile chosen per ISA. */
#if defined(__AVX512F__)
#define VL 16
#define MR 12
#define NV 2
#elif defined(__AVX__)
#define VL 8
#define MR 6
#define NV 2
#elif defined(__aarch64__) || defined(__ARM_NEON)
#define VL 4
#define MR 8
#define NV 3
#else
#define VL 4
#define MR 4
#define NV 2
#endif

#define NR (VL * NV)
#define KC 256
#define IB (MR * ((128 + MR - 1) / MR))
#define JB (NR * ((96 / NR) > 0 ? (96 / NR) : 1))

typedef float vf __attribute__((vector_size(VL * 4)));
typedef float vfu __attribute__((vector_size(VL * 4), aligned(4), may_alias));

static void pack_a(const float *A, float *Ap, int n, int pc, int kc, int p)
{
    int r0 = p * MR;
    for (int i = 0; i < MR; i++) {
        int r = r0 + i;
        if (r < n) {
            const float *src = A + (size_t)r * n + pc;
            for (int k = 0; k < kc; k++) Ap[k * MR + i] = src[k];
        } else {
            for (int k = 0; k < kc; k++) Ap[k * MR + i] = 0.0f;
        }
    }
}

static void pack_b(const float *B, float *Bp, int n, int pc, int kc, int q)
{
    int c0 = q * NR;
    int w = n - c0 < NR ? n - c0 : NR;
    for (int k = 0; k < kc; k++) {
        const float *src = B + (size_t)(pc + k) * n + c0;
        float *dst = Bp + k * NR;
        int j = 0;
        for (; j < w; j++) dst[j] = src[j];
        for (; j < NR; j++) dst[j] = 0.0f;
    }
}

static inline void kernel(int kc, const float *restrict Ap, const float *restrict Bp,
                          float *restrict C, int ldc, int first, int mr, int nr)
{
    vf acc[MR][NV];
#pragma GCC unroll 32
    for (int i = 0; i < MR; i++)
#pragma GCC unroll 4
        for (int v = 0; v < NV; v++) acc[i][v] = (vf){0};

    for (int k = 0; k < kc; k++) {
        vf b[NV];
#pragma GCC unroll 4
        for (int v = 0; v < NV; v++) b[v] = *(const vf *)(Bp + k * NR + v * VL);
#pragma GCC unroll 32
        for (int i = 0; i < MR; i++) {
            float a = Ap[k * MR + i];
#pragma GCC unroll 4
            for (int v = 0; v < NV; v++) acc[i][v] += a * b[v];
        }
    }

    if (mr == MR && nr == NR) {
#pragma GCC unroll 32
        for (int i = 0; i < MR; i++)
#pragma GCC unroll 4
            for (int v = 0; v < NV; v++) {
                vfu *p = (vfu *)(C + (size_t)i * ldc + v * VL);
                if (first) *p = acc[i][v];
                else *p += acc[i][v];
            }
    } else {
        float tmp[MR][NR] __attribute__((aligned(64)));
        for (int i = 0; i < MR; i++)
            for (int v = 0; v < NV; v++) *(vf *)&tmp[i][v * VL] = acc[i][v];
        for (int i = 0; i < mr; i++)
            for (int j = 0; j < nr; j++) {
                if (first) C[(size_t)i * ldc + j] = tmp[i][j];
                else C[(size_t)i * ldc + j] += tmp[i][j];
            }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;
    int npA = (n + MR - 1) / MR;
    int npB = (n + NR - 1) / NR;
    size_t szA = (size_t)npA * MR * KC * sizeof(float);
    size_t szB = (size_t)npB * NR * KC * sizeof(float);
    szA = (szA + 63) & ~(size_t)63;
    szB = (szB + 63) & ~(size_t)63;
    float *Apk = (float *)aligned_alloc(64, szA);
    float *Bpk = (float *)aligned_alloc(64, szB);
    if (!Apk || !Bpk) {
        free(Apk); free(Bpk);
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++) {
                float s = 0.0f;
                for (int k = 0; k < n; k++) s += A[(size_t)i * n + k] * B[(size_t)k * n + j];
                C[(size_t)i * n + j] = s;
            }
        return;
    }

    int ntI = (n + IB - 1) / IB;
    int ntJ = (n + JB - 1) / JB;
    int npack = npA + npB;

#pragma omp parallel if (n >= 64)
    {
        for (int pc = 0; pc < n; pc += KC) {
            int kc = n - pc < KC ? n - pc : KC;
            int first = (pc == 0);

#pragma omp for schedule(dynamic, 2)
            for (int t = 0; t < npack; t++) {
                if (t < npA) pack_a(A, Apk + (size_t)t * MR * KC, n, pc, kc, t);
                else pack_b(B, Bpk + (size_t)(t - npA) * NR * KC, n, pc, kc, t - npA);
            }

#pragma omp for collapse(2) schedule(dynamic, 1)
            for (int ti = 0; ti < ntI; ti++)
                for (int tj = 0; tj < ntJ; tj++) {
                    int i0 = ti * IB, i1 = i0 + IB < n ? i0 + IB : n;
                    int j0 = tj * JB, j1 = j0 + JB < n ? j0 + JB : n;
                    for (int j = j0; j < j1; j += NR) {
                        int nr = j1 - j < NR ? j1 - j : NR;
                        const float *Bp = Bpk + (size_t)(j / NR) * NR * KC;
                        for (int i = i0; i < i1; i += MR) {
                            int mr = i1 - i < MR ? i1 - i : MR;
                            const float *Ap = Apk + (size_t)(i / MR) * MR * KC;
                            kernel(kc, Ap, Bp, C + (size_t)i * n + j, n, first, mr, nr);
                        }
                    }
                }
        }
    }

    free(Apk);
    free(Bpk);
}
